class Node {
  constructor(val) {
    this.val = val;
    this.next = null;
    this.child = null;
  }
}

function flatten(head) {
  if (head === null) return null;
  let curr = head;
  while (curr) {
    if (curr.child) {
      const nxt = curr.next;
      curr.next = curr.child;
      curr.child = null;
      let tail = curr.next;
      while (tail.next) tail = tail.next;
      tail.next = nxt;
    }
    curr = curr.next;
  }
  return head;
}

const a = new Node(1), b = new Node(2), c = new Node(3), d = new Node(4);
a.next = b;
b.next = c;
b.child = d;
const out = [];
for (let n = flatten(a); n; n = n.next) out.push(n.val);
