public class FlattenLL {
    static class Node { int val; Node next, child;
        Node(int v){val=v;} }
    public Node flatten(Node head) {
        if (head == null) return null;
        Node curr = head;
        while (curr != null) {
            if (curr.child != null) {
                Node child = curr.child;
                Node next = curr.next;
                curr.next = child;
                child = flatten(child);
                while (child.next != null) child = child.next;
                child.next = next;
                curr.child = null;
            }
            curr = curr.next;
        }
        return head;
    }
}

