Node* flatten(Node* head) {
    if (!head) return NULL;
    Node* curr = head;
    while (curr) {
        if (curr->child) {
            Node* nxt = curr->next;
            curr->next = curr->child;
            curr->child = NULL;
            Node* tail = curr->next;
            while (tail->next) tail = tail->next;
            tail->next = nxt;
        }
        curr = curr->next;
    }
    return head;
}

